{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Konklusionen (ophør giver ikke i sig selv ret) stemmer med rubrikken. Svaret beskriver korrekt vurderingen af arbejdets karakter, andre typer arbejde og skånehensyn/mindre omfang. Der er ingen af rubrikkens materielle fejl. Formuleringen 'stort set ikke muligt ... i nævneværdigt omfang' er en skærpet parafrase, men den forvansker ikke kernen."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: arbejdets karakter holdes op mod funktionsnedsættelsen, andre typer arbejde vurderes, og skånehensyn/mindre omfang indgår. Svaret nævner også ikke-fysisk belastende arbejde. Formuleringen 'ud fra sagens øvrige oplysninger' er ikke ordret med, men andet arbejde og dokumentation indgår reelt."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge dele af spørgsmålet: om ophør i sig selv giver ret (nej), og hvad Udbetaling Danmark vurderer. Teksten er relevant."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til en identificerbar vejledning (VEJ nr. 10157) og SU-bekendtgørelsen, og påstandene er knyttet til dem med henvisningsnumre."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning 10157 og SU-bekendtgørelsen (841) findes i de frosne kilder og er aktuelle og autoritative. Vejledningens afsnit 3.4.1.3 om arbejdsophør er den relevante passage."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Kilderne understøtter hovedpåstandene om ophør, arbejdets karakter og andre typer arbejde. Flere påstande går dog videre end de viste passager. Det gælder 'stort set ikke er muligt ... i nævneværdigt omfang', 'Udbetaling Danmark vil typisk spørge...', at arbejdsophør er 'et stærkt argument', og kravet om at ophøret 'faktisk skyldes funktionsnedsættelsen og ikke andre forhold'. Disse udsagn er ikke dækket af de angivne passager."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en tærskel, 'stort set ikke muligt at påtage sig erhvervsarbejde i nævneværdigt omfang'. Den står ikke i § 7, stk. 3 eller i bekendtgørelsen. Det samme gælder, at ophør er 'et stærkt argument' og at ophøret skal skyldes funktionsnedsættelsen 'og ikke andre forhold'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer de påkrævede forbehold: arbejdsophør er et udgangspunkt/moment for en nærmere vurdering og ikke afgørende i sig selv. Det angiver også, at skånehensyn, mindre omfang og ikke-fysisk belastende arbejde indgår i vurderingen."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Trinene hænger sammen: lovens kriterium, individuel vurdering, ophør som moment, vurdering af andet arbejde, og så konklusionen at ophør ikke i sig selv er nok."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør enkelte elementer mere absolutte eller bruger andre modaliteter end kilden. Det gælder 'stort set ikke muligt', 'Udbetaling Danmark vil typisk spørge' og 'skal stadig vurdere ... om ansøgeren kan varetage andre typer arbejde' som en uden forbehold formuleret udvidet tærskel/praksis. Kilden siger blot 'ses der på' og 'vurderes'."
    }
  },
  "xhaile_coverage": {
    "A22": {
      "label": "yes",
      "reason": "Svaret dækker, at Udbetaling Danmark ser på arbejdets karakter i forhold til funktionsnedsættelsen, når ansøgeren oplyser, at arbejdet er ophørt på grund af nedsættelsen. Det nævner også ikke-fysisk belastende arbejde."
    },
    "A23": {
      "label": "yes",
      "reason": "Svaret angiver, at Udbetaling Danmark vurderer, om ansøgeren kan varetage andet arbejde, eventuelt med skånehensyn eller i mindre omfang, og nævner arbejde der ikke er fysisk belastende."
    }
  },
  "overall_notes": "Indholdsmæssigt er svaret korrekt og dækker de kritiske elementer. Svaret falder på kildestøtte og tilføjelser, fordi det indfører en skærpet tærskel og enkelte formuleringer ('stærkt argument', 'typisk', 'ikke andre forhold') uden dækning i de viste passager."
}

